const $ = id => document.getElementById(id);
const ids = ['fixedForce','mass','rollingResistance','velocityResistance','initialPosition','initialSpeed','speedTarget','positionTarget','initialIntegral','kpSpeed','kiSpeed','kpPosition','kiPosition','kdPosition','tractionMax','brakeMax','disturbance','disturbanceAt','duration','dt','availableDeceleration','safetyMargin'];
const units = {fixedForce:' N',mass:' kg',rollingResistance:' N',velocityResistance:' N·s/m',initialPosition:' m',initialSpeed:' m/s',speedTarget:' m/s',positionTarget:' m',initialIntegral:'',kpSpeed:' N·s/m',kiSpeed:' N/m',kpPosition:' N/m',kiPosition:' N/(m·s)',kdPosition:' N·s/m',tractionMax:' N',brakeMax:' N',disturbance:' N',disturbanceAt:' s',duration:' s',dt:' s',availableDeceleration:' m/s²',safetyMargin:' m'};
const defaults = Object.fromEntries(ids.map(id=>[id,$(id).value])); defaults.mode=$('mode').value;
let latest=null,playing=true,lastFrameTime=performance.now(),renderRequest;

function parameters(){
  const p=Object.fromEntries(ids.map(id=>[id,Number($(id).value)]));
  return {...p,mode:$('mode').value,nominalDisturbance:0,responseDelay:0};
}
function format(){
  ids.forEach(id=>{const value=Number($(id).value);let digits=0;if(['dt','availableDeceleration'].includes(id))digits=2;else if(['initialSpeed','speedTarget'].includes(id))digits=1;const text=Math.abs(value)>=10000?value.toLocaleString():value.toFixed(digits);document.querySelector(`[data-for="${id}"]`).textContent=text+units[id]});
}
function sampled(frames,limit=2400){if(frames.length<=limit)return frames;const stride=Math.ceil((frames.length-1)/(limit-1));const data=frames.filter((_,i)=>i%stride===0);if(data.at(-1)!==frames.at(-1))data.push(frames.at(-1));return data}
function canvasSetup(canvas){const ratio=devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*ratio;canvas.height=h*ratio;const c=canvas.getContext('2d');c.scale(ratio,ratio);c.clearRect(0,0,w,h);return{c,w,h}}
function drawChart(canvas,frames,series,{target=null,zero=true}={}){
  const data=sampled(frames),{c,w,h}=canvasSetup(canvas),pad={l:62,r:18,t:12,b:32};let values=data.flatMap(d=>series.map(s=>s.value(d))).filter(Number.isFinite);if(target!==null)values.push(target);if(zero)values.push(0);let low=Math.min(...values),high=Math.max(...values);const gap=(high-low||1)*.1;low-=gap;high+=gap;const duration=frames.at(-1).time,x=t=>pad.l+t/duration*(w-pad.l-pad.r),y=v=>h-pad.b-(v-low)/(high-low)*(h-pad.t-pad.b);
  c.font='10px ui-monospace,monospace';c.fillStyle='#778087';c.strokeStyle='#dedbd1';c.lineWidth=1;
  for(let i=0;i<=4;i++){const value=low+(high-low)*i/4,py=y(value);c.beginPath();c.moveTo(pad.l,py);c.lineTo(w-pad.r,py);c.stroke();c.fillText(Math.abs(value)>=1000?(value/1000).toFixed(1)+'k':value.toFixed(1),7,py+3)}
  for(let i=0;i<=5;i++){const t=duration*i/5;c.fillText(Math.round(t)+'s',x(t)-10,h-9)}
  if(target!==null){c.strokeStyle='#ff6b35';c.setLineDash([6,5]);c.beginPath();c.moveTo(pad.l,y(target));c.lineTo(w-pad.r,y(target));c.stroke();c.setLineDash([])}
  series.forEach(s=>{c.strokeStyle=s.color;c.lineWidth=s.width||2;c.setLineDash(s.dash||[]);c.beginPath();data.forEach((d,i)=>i?c.lineTo(x(d.time),y(s.value(d))):c.moveTo(x(d.time),y(s.value(d))));c.stroke();c.setLineDash([])});
}
function drawMemory(canvas,frames,p){
  const {c,w,h}=canvasSetup(canvas),mid=h/2,data=sampled(frames),duration=frames.at(-1).time,pad={l:62,r:18,t:10,b:24};
  const errorValue=d=>p.mode.startsWith('speed_')?d.control.speedError:d.control.positionError;
  const drawPanel=(top,bottom,value,color,label)=>{const vals=data.map(value);let low=Math.min(0,...vals),high=Math.max(0,...vals),gap=(high-low||1)*.1;low-=gap;high+=gap;const x=t=>pad.l+t/duration*(w-pad.l-pad.r),y=v=>bottom-(v-low)/(high-low)*(bottom-top);c.strokeStyle='#dedbd1';c.beginPath();c.moveTo(pad.l,y(0));c.lineTo(w-pad.r,y(0));c.stroke();c.strokeStyle=color;c.lineWidth=2;c.beginPath();data.forEach((d,i)=>i?c.lineTo(x(d.time),y(value(d))):c.moveTo(x(d.time),y(value(d))));c.stroke();c.fillStyle='#68727a';c.font='10px ui-monospace,monospace';c.fillText(label,8,top+13);c.fillText(high.toFixed(1),8,top+28);c.fillText(low.toFixed(1),8,bottom)};
  drawPanel(pad.t,mid-12,errorValue,'#d87821',p.mode.startsWith('speed_')?'speed error (m/s)':'position error (m)');drawPanel(mid+12,h-pad.b,d=>d.z,'#7959a8',p.mode==='speed_pi'?'integral z (m)':p.mode.startsWith('position_pid')?'integral z (m·s)':'integral unused');
}
function currentFrame(){return latest?latest.run.frames[Number($('animationTime').value)]:null}
function outcome(run,p){const f=run.final,positionMode=p.mode.startsWith('position_'),positionError=p.positionTarget-f.x;if(positionMode){if(f.v<.05&&Math.abs(positionError)<=1)return{label:'stopped at target',detail:`${positionError.toFixed(2)} m error`};if(f.v<.05)return{label:'stopped elsewhere',detail:`${positionError.toFixed(1)} m error`};if(f.x>=p.positionTarget)return{label:'crossed at speed',detail:`${f.v.toFixed(2)} m/s remains`};return{label:'not stopped',detail:`${positionError.toFixed(1)} m remains`}}return{label:`${f.v.toFixed(2)} m/s final`,detail:`${(p.speedTarget-f.v).toFixed(2)} m/s speed error`}}
function updateAnimation(){
  const d=currentFrame();if(!d)return;const p=latest.p,span=Math.max(1,p.positionTarget-p.initialPosition),progress=Math.max(0,Math.min(1.18,(d.x-p.initialPosition)/span)),left=7+61*progress;$('trainStage').style.setProperty('--train-left',`${left}%`);$('stationLabel').textContent=`${p.positionTarget.toFixed(0)} m`;$('scaleStart').textContent=`start ${p.initialPosition.toFixed(0)} m`;$('scaleStation').textContent=`station ${p.positionTarget.toFixed(0)} m`;
  const forceScale=Math.max(p.tractionMax,p.brakeMax,1),actuatorWidth=20+80*Math.min(1,Math.abs(d.applied)/forceScale),resistance=Math.abs(d.rolling+d.velocity+d.disturbance),resistanceWidth=18+62*Math.min(1,resistance/forceScale);$('actuatorArrow').style.width=`${actuatorWidth}px`;$('resistanceArrow').style.width=`${resistanceWidth}px`;$('actuatorArrow').style.opacity=Math.abs(d.applied)>1?'1':'0';$('resistanceArrow').style.opacity=resistance>1?'1':'0';$('actuatorArrow').classList.toggle('brake',d.applied<0);$('actuatorArrowLabel').textContent=d.applied>1?'traction':d.applied<-1?'active brake':'coast';
  $('animatedPosition').textContent=`x = ${d.x.toFixed(2)} m`;$('animatedSpeed').textContent=`v = ${d.v.toFixed(2)} m/s`;$('motionState').textContent=d.v<.01?'STOPPED':d.acceleration>.01?'ACCELERATING':d.acceleration<-.01?'BRAKING / DECELERATING':'NEAR CONSTANT SPEED';
  const positionMode=p.mode.startsWith('position_'),error=positionMode?d.control.positionError:d.control.speedError,errorUnit=positionMode?'m':'m/s';$('liveError').textContent=`e = ${error.toFixed(3)} ${errorUnit}`;$('liveController').textContent=`${(d.control.bias+d.control.proportional+d.control.integral+d.control.derivative).toFixed(0)} N requested`;$('liveForce').textContent=`clip → ${d.applied.toFixed(0)} N ${d.saturated?'(SATURATED)':''}`;$('liveAcceleration').textContent=`${d.net.toFixed(0)} N / ${p.mass.toFixed(0)} kg = ${d.acceleration.toFixed(4)} m/s²`;$('liveEuler').textContent=`x⁺ ${d.nextState.x.toFixed(2)} m · v⁺ ${d.nextState.v.toFixed(3)} m/s`;$('liveFeasibility').textContent=`remaining ${d.feasibility.remaining.toFixed(1)} m · stop est. ${d.feasibility.stopDistance.toFixed(1)} m`;
  $('metricPosition').textContent=`${d.x.toFixed(2)} m`;$('metricRemaining').textContent=`${d.feasibility.remaining.toFixed(2)} m remaining`;$('metricSpeed').textContent=`${d.v.toFixed(2)} m/s`;$('metricMotion').textContent=d.v<.01?'at standstill':`${(d.v*3.6).toFixed(1)} km/h`;$('metricForce').textContent=`${(d.applied/1000).toFixed(2)} kN`;$('metricForceMode').textContent=d.applied>1?'traction':d.applied<-1?'active braking':'coast / hold';$('metricMargin').textContent=`${d.feasibility.margin.toFixed(1)} m`;$('metricFeasible').textContent=d.feasibility.feasible?'configured estimate feasible':'configured estimate infeasible';$('metricIntegral').textContent=d.z.toFixed(2);$('metricIntegralUnits').textContent=p.mode==='speed_pi'?'m (speed-error memory)':p.mode.startsWith('position_pid')?'m·s (position-error memory)':'integral not used';$('animationClock').textContent=`${d.time.toFixed(2)} s`;
}
function comparison(p){
  for(const [prefix,mode] of [['P','position_p'],['PD','position_pd'],['PID','position_pid_aw']]){const run=TrainModel.simulate({...p,mode}),f=run.final,overshoot=Math.max(0,...run.frames.map(d=>d.x-p.positionTarget)),result=outcome(run,{...p,mode});$(`compare${prefix}Position`).textContent=`${f.x.toFixed(1)} m`;$(`compare${prefix}Overshoot`).textContent=`${overshoot.toFixed(1)} m`;$(`compare${prefix}Outcome`).textContent=result.label}
}
function render(){
  const oldProgress=latest?Number($('animationTime').value)/Math.max(1,latest.run.frames.length-1):0,p=parameters();if(p.disturbanceAt>p.duration){$('disturbanceAt').value=p.duration;p.disturbanceAt=p.duration}format();const run=TrainModel.simulate(p);latest={p,run};
  drawChart($('positionChart'),run.frames,[{value:d=>d.x,color:'#087f83',width:2.5}],{target:p.positionTarget});drawChart($('speedChart'),run.frames,[{value:d=>d.v,color:'#2479bf',width:2.5}],{target:p.speedTarget});drawChart($('forceChart'),run.frames,[{value:d=>d.request,color:'#d87821',dash:[5,4]},{value:d=>d.applied,color:'#10263f',width:2.5}]);drawMemory($('memoryChart'),run.frames,p);drawChart($('safetyChart'),run.frames,[{value:d=>d.feasibility.remaining,color:'#087f83'},{value:d=>d.feasibility.stopDistance,color:'#d87821'}]);
  $('animationTime').max=String(run.frames.length-1);$('animationTime').value=String(Math.round(oldProgress*(run.frames.length-1)));const finalOutcome=outcome(run,p);$('metricOutcome').textContent=finalOutcome.label;$('metricFinalError').textContent=finalOutcome.detail;const mode=p.mode.replaceAll('_',' ');$('insightText').textContent=p.mode==='speed_p'?'Biased P balances the nominal resistance, but an unknown constant opposing force requires a lasting speed error.':p.mode==='speed_pi'?'PI stores speed error in metres. In unsaturated stable operation, that memory can supply the constant missing force while current speed error returns toward zero.':p.mode==='position_p'?'Position P sees distance but not approach speed, so it can command traction even when braking is already needed.':p.mode==='position_pd'?'The −Kd·v term adds velocity damping for a fixed station, but damping alone is not a stopping-safety guarantee.':p.mode.includes('pid')?'PID combines position error, accumulated position error and velocity damping. Anti-windup limits stored error; the optional supervisor separately checks stopping feasibility.':'Open-loop force does not react to speed, position or disturbance.';$('equation').textContent=`${mode}: Fraw ${run.final.control.raw.toFixed(0)} N → Fapplied ${run.final.applied.toFixed(0)} N`;comparison(p);updateAnimation();
}
function setPreset(values){for(const [key,value] of Object.entries(values)){if(key==='mode')$('mode').value=value;else $(key).value=String(value)}latest=null;playing=true;$('playAnimation').textContent='Pause';render()}
function animate(now){if(playing&&latest){const count=latest.run.frames.length;let next=Number($('animationTime').value)+(now-lastFrameTime)/15000*count;if(next>=count-1)next=0;$('animationTime').value=String(Math.floor(next));updateAnimation()}lastFrameTime=now;requestAnimationFrame(animate)}
function schedule(){cancelAnimationFrame(renderRequest);renderRequest=requestAnimationFrame(render)}
ids.forEach(id=>$(id).addEventListener('input',schedule));$('mode').addEventListener('change',schedule);$('animationTime').addEventListener('input',()=>{playing=false;$('playAnimation').textContent='Play';updateAnimation()});$('playAnimation').onclick=()=>{playing=!playing;$('playAnimation').textContent=playing?'Pause':'Play'};$('stepAnimation').onclick=()=>{playing=false;$('playAnimation').textContent='Play';$('animationTime').value=String(Math.min(Number($('animationTime').max),Number($('animationTime').value)+1));updateAnimation()};$('reset').onclick=()=>setPreset({...defaults,mode:defaults.mode});$('presetSpeed').onclick=()=>setPreset({mode:'speed_pi',initialPosition:0,initialSpeed:15,initialIntegral:0,disturbance:3000,disturbanceAt:80,duration:180,dt:.1,speedTarget:25,positionTarget:500});$('presetStation').onclick=()=>setPreset({mode:'position_pid_supervisor',initialPosition:400,initialSpeed:20,initialIntegral:0,disturbance:0,disturbanceAt:60,duration:60,dt:.1,positionTarget:500,availableDeceleration:1,safetyMargin:0});$('presetWindup').onclick=()=>setPreset({mode:'position_pid_aw',initialPosition:0,initialSpeed:0,initialIntegral:0,disturbance:0,disturbanceAt:60,duration:150,dt:.1,positionTarget:500});window.addEventListener('resize',schedule);render();requestAnimationFrame(animate);
